local GrenadeMaker = {}
local PRODUCTS = {
    clay_grenade = { name = "Glina granata", clayCost = 2, gunpowderCost = 1, time = 1, cost = 20, attack = 25, radius = 3, durability = 5, description = "Glina granata za pehoto." },
    iron_grenade = { name = "Železna granata", ironCost = 1, gunpowderCost = 1, time = 2, cost = 60, attack = 45, radius = 4, durability = 8, prestige = 1, description = "Železna granata z močno eksplozijo." },
    steel_grenade = { name = "Jeklena granata", steelCost = 1, gunpowderCost = 2, time = 4, cost = 160, attack = 70, radius = 5, durability = 12, prestige = 3, happiness = 1, description = "Jeklena granata za viteze." },
    silver_decorated_grenade = { name = "Srebrno okrašena granata", steelCost = 1, silverCost = 1, gunpowderCost = 2, time = 6, cost = 380, attack = 100, radius = 6, durability = 16, prestige = 7, happiness = 2, description = "Granata s srebrnim okrasjem za plemiče." },
    gold_inlaid_grenade = { name = "Zlatorobna granata", steelCost = 2, goldCost = 1, silverCost = 1, gunpowderCost = 3, time = 9, cost = 850, attack = 140, radius = 8, durability = 22, prestige = 14, happiness = 3, description = "Granata z zlatorobnim okovjem za visoke častnike." },
    royal_ceremonial_grenade = { name = "Kraljevski slovesna granata", steelCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, gunpowderCost = 4, time = 14, cost = 2000, attack = 220, radius = 12, durability = 35, prestige = 38, happiness = 8, description = "Velika kraljevska slovesna granata z dragulji in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Granatna delavnica", cost = { gold = 280, wood = 120, stone = 150 }, upkeep = 7, qualityBonus = 5 },
    powder_room = { name = "Smodniška soba", cost = { gold = 900, wood = 220, stone = 300, gunpowder = 8 }, upkeep = 22, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 2200, wood = 280, stone = 500, silver = 40, steel = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_grenade_atelier = { name = "Kraljevski atelje granat", cost = { gold = 8500, wood = 500, stone = 800, gold = 80, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 35 },
}
GrenadeMaker.clayStock = 14; GrenadeMaker.ironStock = 12; GrenadeMaker.steelStock = 12; GrenadeMaker.silverStock = 8; GrenadeMaker.goldStock = 6; GrenadeMaker.jewelStock = 6; GrenadeMaker.pearlStock = 4; GrenadeMaker.gunpowderStock = 16
GrenadeMaker.productStock = {}; GrenadeMaker.buildings = {}; GrenadeMaker.maker = nil; GrenadeMaker.activeMaking = {}; GrenadeMaker.totalProducts = 0; GrenadeMaker.dayTimer = 0
function GrenadeMaker.init() GrenadeMaker.clayStock=14; GrenadeMaker.ironStock=12; GrenadeMaker.steelStock=12; GrenadeMaker.silverStock=8; GrenadeMaker.goldStock=6; GrenadeMaker.jewelStock=6; GrenadeMaker.pearlStock=4; GrenadeMaker.gunpowderStock=16; GrenadeMaker.productStock={}; GrenadeMaker.buildings={}; GrenadeMaker.maker=nil; GrenadeMaker.activeMaking={}; GrenadeMaker.totalProducts=0; GrenadeMaker.dayTimer=0; print("[GrenadeMaker] Royal Grenade Maker System initialized (6 products, 4 buildings)") end
function GrenadeMaker.hireMaker(n,s) s=s or math.random(50,90); local c=550+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrenadeMaker.maker={name=n or ("Granatar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Granatar najet: %s (spretnost: %d)",GrenadeMaker.maker.name,s),"success") end; return true end
function GrenadeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrenadeMaker.build(id) local ok,e=GrenadeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrenadeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrenadeMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrenadeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrenadeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and GrenadeMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.ironCost and GrenadeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and GrenadeMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and GrenadeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrenadeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrenadeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrenadeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if d.gunpowderCost and GrenadeMaker.gunpowderStock<(d.gunpowderCost or 0) then return false,"Premalo smodnika" end; if #GrenadeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not GrenadeMaker.maker then return false,"Potreben granatar" end; return true end
function GrenadeMaker.make(pt,qty) qty=qty or 5; local ok,e=GrenadeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then GrenadeMaker.clayStock=GrenadeMaker.clayStock-d.clayCost*qty end; if d.ironCost then GrenadeMaker.ironStock=GrenadeMaker.ironStock-d.ironCost*qty end; if d.steelCost then GrenadeMaker.steelStock=GrenadeMaker.steelStock-d.steelCost*qty end; if d.silverCost then GrenadeMaker.silverStock=GrenadeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrenadeMaker.goldStock=GrenadeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrenadeMaker.jewelStock=GrenadeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrenadeMaker.pearlStock=GrenadeMaker.pearlStock-d.pearlCost*qty end; if d.gunpowderCost then GrenadeMaker.gunpowderStock=GrenadeMaker.gunpowderStock-d.gunpowderCost*qty end; local t=d.time; if GrenadeMaker.maker then t=math.max(1,t-math.floor(GrenadeMaker.maker.skill/12)) end; table.insert(GrenadeMaker.activeMaking,{id="grenade_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,radius=d.radius or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrenadeMaker.completeMaking(m) local q=1.0+(GrenadeMaker.getQualityBonus()/100); if GrenadeMaker.maker then q=q+(GrenadeMaker.maker.skill/180) end; q=math.min(2.0,q); GrenadeMaker.productStock[m.productType]=(GrenadeMaker.productStock[m.productType] or 0)+m.quantity; GrenadeMaker.totalProducts=GrenadeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrenadeMaker.maker then GrenadeMaker.maker.itemsMade=GrenadeMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then GrenadeMaker.maker.skill=math.min(100,GrenadeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Granate izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grenade.completed",{productName=m.productName,attack=m.attack,radius=m.radius,durability=m.durability}) end end
function GrenadeMaker.update(dt) if not _G.state then return end; GrenadeMaker.dayTimer=GrenadeMaker.dayTimer+dt; if GrenadeMaker.dayTimer>=30 then GrenadeMaker.dayTimer=0; for i=#GrenadeMaker.activeMaking,1,-1 do local m=GrenadeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrenadeMaker.completeMaking(m); table.remove(GrenadeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrenadeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrenadeMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrenadeMaker.getStats() return {clayStock=GrenadeMaker.clayStock,ironStock=GrenadeMaker.ironStock,steelStock=GrenadeMaker.steelStock,silverStock=GrenadeMaker.silverStock,goldStock=GrenadeMaker.goldStock,jewelStock=GrenadeMaker.jewelStock,pearlStock=GrenadeMaker.pearlStock,gunpowderStock=GrenadeMaker.gunpowderStock,productStock=GrenadeMaker.productStock,numBuildings=#GrenadeMaker.buildings,hasMaker=GrenadeMaker.maker~=nil,makerName=GrenadeMaker.maker and GrenadeMaker.maker.name or "—",makerSkill=GrenadeMaker.maker and GrenadeMaker.maker.skill or 0,activeMaking=#GrenadeMaker.activeMaking,totalProducts=GrenadeMaker.totalProducts} end
return GrenadeMaker
